---

@import url("https://fonts.cdnfonts.com/css/thegoodmonolith");
@import url("https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&display=swap");

@font-face {
  font-family: "PP Neue Montreal";
  src: url("https://fonts.cdnfonts.com/s/64587/PPNeueMontreal-Medium.woff2")
    format("woff2");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}

/* ===== CSS VARIABLES ===== */
:root {
  /* Colors */
  --color-bg: #111111;
  --color-text: #ffffff;
  --color-text-muted: rgba(255, 255, 255, 0.7);
  --color-text-dim: rgba(255, 255, 255, 0.6);
  --color-dot: #444;
  --color-star: rgba(209, 255, 255, 1);
  /* Typography */
  --font-body: "TheGoodMonolith", sans-serif;
  --font-title: "PP Neue Montreal", sans-serif;
  --font-size-small: 1rem;
  --font-size-base: 1.5rem;
  --font-size-h2: 2.5rem;
  --font-size-h1: 3rem;
  --font-size-XL: 5rem;
  --letter-spacing-title: -0.03em;
  --line-height: 1.4;
  /* Spacing */
  --spacing-base: 1rem;
  --spacing-sm: 0.75rem;
  --spacing-xs: 0.25rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 4rem;
  /* Transitions */
  --transition-fast: 0.15s ease;
  --transition-medium: 0.3s ease;
  --transition-slow: 0.8s ease;
  /* Effects */
  --blur-amount: 5px;
}

/* ===== RESET & BASE STYLES ===== */
*,
*:before,
*:after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.underline {
  text-decoration: underline;
}

body {
  font-family: var(--font-body);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: var(--line-height);
  margin: 0;
  font-size: var(--font-size-base);
  overflow-x: hidden;
}

body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url("https://img.freepik.com/premium-photo/white-dust-scratches-black-background_279525-2.jpg?w=640");
  background-repeat: repeat;
  opacity: 0.05;
  mix-blend-mode: screen;
  pointer-events: none;
  z-index: 1;
}

h2,
h3 {
  font-weight: normal;
  margin-bottom: var(--spacing-sm);
}

h2 {
  font-family: var(--font-title);
  font-size: var(--font-size-h2);
  letter-spacing: var(--letter-spacing-title);
  text-transform: uppercase;
  margin-bottom: var(--spacing-md);
}

p {
  margin-bottom: var(--spacing-xs);
  font-size: var(--font-size-base);
  opacity: 0.7;
}

ul {
  list-style: none;
}

li {
  margin-bottom: var(--spacing-xs);
  font-size: var(--font-size-base);
  opacity: 0.7;
}

li a {
  color: inherit;
  font-size: inherit;
  opacity: inherit;
  text-decoration: none;
}

a,
.links span {
  position: relative;
  cursor: pointer;
  color: var(--color-text);
  padding: 0;
  display: inline-block;
  z-index: 1;
  text-decoration: none;
  font-size: var(--font-size-base);
  opacity: 0.7;
  transition: color var(--transition-medium);
}

a::after,
.links span::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 0;
  height: 100%;
  background-color: var(--color-text);
  z-index: -1;
  transition: width 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

a:hover::after,
.links span:hover::after {
  width: 100%;
}

a:hover,
.links span:hover {
  color: black;
  mix-blend-mode: difference;
  opacity: 1;
}

/* ===== LAYOUT ===== */
.footer {
  padding: var(--spacing-lg);
  width: 100%;
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ===== BOTTOM BAR ===== */
.bottom-bar {
  margin-top: auto;
  padding-top: var(--spacing-lg);
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  column-gap: var(--spacing-base);
  align-items: flex-end;
  width: 100%;
  position: relative;
  z-index: 5;
}

.coordinates {
  grid-column: 1 / span 3;
  opacity: var(--color-text-dim);
}

.links {
  grid-column: 5 / span 4;
  text-align: center;
}

.info {
  grid-column: 9 / span 4;
  text-align: right;
  opacity: var(--color-text-dim);
}

.links span {
  margin: 0 var(--spacing-base);
}

/* ===== DOT GRID ===== */
.dot-grid {
  width: 100%;
  height: 150px;
  position: relative;
  margin-top: var(--spacing-base);
  overflow: hidden;
  z-index: 1;
}

.dot {
  position: absolute;
  font-size: 10px;
  color: var(--color-dot);
  transition: all var(--transition-fast);
  will-change: transform, color;
}

/* ===== WEBGL SECTION ===== */
.sticky-container {
  position: relative;
  height: 500vh;
  width: 100%;
  margin: 0;
}

.webgl-section {
  position: sticky;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 10;
  overflow: hidden;
  will-change: transform, opacity, filter;
}

.canvas-container {
  width: 100%;
  height: 100%;
  position: relative;
  will-change: transform, opacity, filter;
  display: flex;
  justify-content: center;
  align-items: center;
}

canvas#space {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: block;
}

/* ===== ANIMATED TEXT ===== */
.animated-text {
  position: absolute;
  top: auto;
  left: 50%;
  transform: translate(-50%, calc(-50% + 40px));
  color: var(--color-text);
  font-family: var(--font-title);
  font-size: clamp(2rem, 15vw, 5rem);
  text-align: center;
  opacity: 0;
  z-index: 20;
  text-transform: uppercase;
  letter-spacing: var(--letter-spacing-title);
  pointer-events: none;
  width: 80%;
  max-width: 800px;
  will-change: opacity, transform, filter;
  filter: blur(8px);
  transition: filter 1.2s cubic-bezier(0.16, 1, 0.3, 1);
}

/* ===== ABOUT SECTION (WHO IS LUCID) ===== */
.social-icons {
  grid-column: 5 / span 4;
  display: flex;
  flex-direction: row;
  gap: var(--spacing-base);
  justify-content: center;
  align-items: center;
  z-index: 5;
}

.social-icons a {
  color: var(--color-text);
  opacity: 0.8;
  transition: opacity var(--transition-medium), filter var(--transition-medium);
  display: flex;
  filter: drop-shadow(0 0 6px rgba(209, 255, 255, 0.6));
}

.social-icons a::after {
  display: none;
}

.social-icons a:hover {
  opacity: 1;
  color: var(--color-text);
  mix-blend-mode: normal;
  filter: drop-shadow(0 0 12px rgba(209, 255, 255, 1)) drop-shadow(0 0 24px rgba(209, 255, 255, 0.5));
}

.social-icons svg {
  width: 40px;
  height: 40px;
}

.additional-section {
  width: 100%;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: var(--spacing-xl) var(--spacing-lg);
  position: relative;
  z-index: 20;
  overflow: visible;
}

.additional-content {
  width: 100%;
  max-width: 800px;
  text-align: left;
  opacity: 0;
  transform: translateY(30px);
  transition: opacity var(--transition-slow), transform var(--transition-slow);
  font-family: "JetBrains Mono", monospace;
}

.lanyard-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
  font-family: "JetBrains Mono", monospace;
  margin-bottom: var(--spacing-md);
  margin-left: auto;
  margin-right: auto;
}

.lanyard-avatar-wrap {
  position: relative;
}

.lanyard-card a {
  display: inline-block;
}

.lanyard-card a::after {
  display: none;
}

.lanyard-card a:hover {
  color: inherit;
  mix-blend-mode: normal;
  opacity: 1;
}

.lanyard-avatar-hover {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid rgba(255, 255, 255, 0.15);
  filter: drop-shadow(0 0 8px rgba(209, 255, 255, 0.4));
}

.lanyard-avatar-hover canvas {
  border-radius: 50%;
}

.lanyard-status-dot {
  position: absolute;
  bottom: 4px;
  right: 4px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 3px solid var(--color-bg);
}

.lanyard-status-dot.online { background: #43b581; }
.lanyard-status-dot.idle { background: #faa61a; }
.lanyard-status-dot.dnd { background: #f04747; }
.lanyard-status-dot.offline { background: #747f8d; }

.lanyard-status-text {
  font-size: 0.9rem;
  color: var(--color-text-muted);
  opacity: 1;
  text-align: center;
}

.additional-content.visible {
  opacity: 1;
  transform: translateY(0);
}

.additional-content .no-margin {
  margin-bottom: 0;
}

.additional-content .interests-list {
  text-align: left;
  max-width: 640px;
  margin: 0.5rem auto var(--spacing-md);
  padding-left: 1.5rem;
  list-style: disc;
}

.additional-content .interests-list li {
  font-size: 1.2rem;
  line-height: 1.6;
  opacity: 0.8;
  margin-bottom: 0.25rem;
}

.additional-content p {
  font-size: 1.2rem;
  line-height: 1.6;
  opacity: 0.8;
  margin-bottom: var(--spacing-md);
}

.slide-title {
  overflow: hidden;
  cursor: default;
}

.slide-title-inner {
  display: inline-block;
  position: relative;
  transition: transform 0.4s cubic-bezier(0.76, 0, 0.24, 1);
}

.slide-text-primary,
.slide-text-secondary {
  display: block;
  text-decoration: underline;
}

.slide-text-secondary {
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
}

.slide-title:hover .slide-title-inner {
  transform: translateY(-100%);
}

.float-in {
  opacity: 0;
  transform: translateY(40px);
}

.terminal-cursor {
  animation: blink 1s step-end infinite;
  font-weight: 700;
  opacity: 1;
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

.section-transition {
  position: relative;
  overflow: hidden;
}



.tagline {
  text-align: center;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.9rem;
  opacity: 0.5;
  margin-top: var(--spacing-sm);
  padding-bottom: var(--spacing-base);
}

/* ===== MOBILE ===== */
@media (max-width: 800px) {
  html {
    font-size: 85%;
  }
}

