import os
from pathlib import Path
from google import genai
from google.genai import errors, types
from vega.config import Settings

# Use the running server's settings precedence, without printing its environment.
pid = 486044
raw = Path(f'/proc/{pid}/environ').read_bytes().split(b'\0')
running_env = dict(os.fsdecode(item).split('=', 1) for item in raw if b'=' in item)
keys = ('VEGA_GEMINI_API_KEY', 'GEMINI_API_KEY', 'VEGA_GEMINI_MODEL')
for name in keys:
    if name in running_env:
        os.environ[name] = running_env[name]
    else:
        os.environ.pop(name, None)
if running_env.get('GOOGLE_GENAI_USE_VERTEXAI', '').lower() in ('1','true') or running_env.get('GOOGLE_GEMINI_BASE_URL'):
    raise SystemExit('Backend uses a non-default API route; skipped direct quota probe.')
s = Settings()
if not s.gemini_api_key:
    raise SystemExit('No configured Gemini API key; no request sent.')
try:
    # One tiny request, no retries, no VEGA telemetry or incident data sent.
    with genai.Client(vertexai=False, api_key=REDACTED, http_options=types.HttpOptions(
        base_url='https://generativelanguage.googleapis.com', timeout=8000,
        retry_options=types.HttpRetryOptions(attempts=1),
    )) as client:
        client.models.generate_content(model=s.gemini_model, contents='Reply OK.', config=types.GenerateContentConfig(max_output_tokens=8))
    print(f'{s.gemini_model}: current provider probe succeeded (HTTP 200).')
except errors.APIError as exc:
    print(f'{s.gemini_model}: HTTP {exc.code} {exc.status or ""}')
    details = getattr(exc, 'details', None)
    if isinstance(details, dict):
        details = details.get('error', details).get('details', [])
    for detail in details or []:
        if not isinstance(detail, dict):
            continue
        kind = detail.get('@type', '')
        if kind.endswith('QuotaFailure'):
            for violation in detail.get('violations', []):
                print('Quota:', violation.get('quotaId', 'unknown'), 'metric:', violation.get('quotaMetric', 'unknown'))
        elif kind.endswith('RetryInfo'):
            print('Provider retry delay:', detail.get('retryDelay', 'unknown'))
except Exception as exc:
    print(f'Provider probe did not complete: {type(exc).__name__}.')
PY

