import os, re
from pathlib import Path
from google import genai
from google.genai import errors, types
from vega.config import Settings
from vega.swarm.scouts import ScoutChunkOutput

raw = Path('/proc/486044/environ').read_bytes().split(b'\0')
running_env = dict(os.fsdecode(item).split('=', 1) for item in raw if b'=' in item)
for name in ('VEGA_GEMINI_API_KEY', 'GEMINI_API_KEY', 'VEGA_GEMINI_MODEL'):
    if name in running_env:
        os.environ[name] = running_env[name]
    else:
        os.environ.pop(name, None)
s = Settings()
if not s.gemini_api_key or running_env.get('GOOGLE_GEMINI_BASE_URL') or running_env.get('GOOGLE_GENAI_USE_VERTEXAI', '').lower() in ('1', 'true'):
    raise SystemExit('Probe skipped: no configured direct Gemini route.')
try:
    with genai.Client(vertexai=False, api_key=REDACTED, http_options=types.HttpOptions(
        base_url='https://generativelanguage.googleapis.com', timeout=10000, retry_options=types.HttpRetryOptions(attempts=1),
    )) as client:
        client.models.generate_content(
            model=s.gemini_model, contents='There are no events. Return an empty list of findings.',
            config=types.GenerateContentConfig(response_mime_type='application/json', response_schema=ScoutChunkOutput, temperature=0.1),
        )
    print(f'{s.gemini_model}: current scout-format probe succeeded (HTTP 200).')
except errors.APIError as exc:
    print(f'{s.gemini_model}: HTTP {exc.code} {exc.status or ""}')
    message = str(exc.message or '').replace(s.gemini_api_key, '[redacted]')
    print(re.sub(r'AIza[A-Za-z0-9_-]+', '[redacted]', message)[:700])
    details = getattr(exc, 'details', None)
    if isinstance(details, dict):
        details = details.get('error', details).get('details', [])
    for detail in details or []:
        if isinstance(detail, dict) and detail.get('reason'):
            print('Provider reason:', detail['reason'])
        if isinstance(detail, dict) and detail.get('retryDelay'):
            print('Provider retry delay:', detail['retryDelay'])
except Exception as exc:
    print(f'Provider probe did not complete: {type(exc).__name__}.')
PY

