                      {wardenDecision.proposed_action}
                    </div>
                  </div>
}

.vega-blackout {
  background: linear-gradient(180deg, rgb(18 5 12 / .16), rgb(9 4 11 / .22) 60%, rgb(9 4 11 / .56));
}

.vega-warden-hero::before {
  content: '';
  position: absolute;
  inset: -1.75rem -2rem -2.5rem;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 46% 34%, rgb(248 113 113 / .16), transparent 63%),
    radial-gradient(ellipse at 50% 62%, rgb(13 6 13 / .44), transparent 72%);
  backdrop-filter: blur(7px) saturate(135%) brightness(.76);
  mask-image: radial-gradient(ellipse closest-side, #000 30%, rgb(0 0 0 / .75) 62%, transparent);
}

.vega-warden-pupil-scan {
  transform-box: view-box;
  transform-origin: 18px 12px;
  transform: scale(1.05, 1.25);
  animation: vega-warden-scan 6s cubic-bezier(.4, 0, .22, 1) infinite;
}

/* The slit just overshoots the curved lids, so the clip holds both tips against the eye. */
@keyframes vega-warden-scan {
  0%, 45.5%, 100% { transform: translateX(0) scale(1.05, 1.25); }
  15%, 36% { transform: translateX(-8px) scale(.72, 1.06); }
  55%, 80% { transform: translateX(6.5px) scale(.72, 1.1); }
}

@media (prefers-reduced-motion: reduce) {
