@import "tailwindcss";

@layer base {
  :root {
    --vega-bg: #050811;
    --vega-surface: rgba(10, 16, 30, 0.78);
    --vega-border: rgba(148, 163, 184, 0.16);
    --vega-accent: #38bdf8;
    --vega-accent-glow: rgba(56, 189, 248, 0.28);
    --vega-oracle: #7851a9;
    --vega-warden: #ef4444;
    --font-sans: 'Space Grotesk', ui-sans-serif, system-ui, -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  }

  [data-threat-mode='WATCH'] {
    --vega-accent: #38bdf8;
    --vega-accent-glow: rgba(56, 189, 248, 0.28);
  }

  [data-threat-mode='INVESTIGATE'] {
    --vega-accent: var(--vega-oracle);
    --vega-accent-glow: color-mix(in srgb, var(--vega-oracle) 32%, transparent);
  }

  [data-threat-mode='SEV1_ESCALATION'],
  [data-threat-mode='CONTAINED'] {
    --vega-accent: #ef4444;
    --vega-accent-glow: rgba(239, 68, 68, 0.38);
  }

  html,
  body,
  #root {
    height: 100%;
    width: 100%;
    overflow: hidden;
    font-family: var(--font-sans);
    background-color: var(--vega-bg);
  }
}

.font-mono-tabular {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.vega-panel {

.vega-eye-scan {
  animation: vega-eye-scan 4s ease-in-out infinite;
}

@keyframes vega-eye-scan {
  0%, 12%, 82%, 100% { transform: translateX(0); }
  23%, 42% { transform: translateX(-3.4px); }
  55%, 72% { transform: translateX(3.4px); }
}

.vega-blackout {
  background: linear-gradient(180deg, rgb(18 5 12 / .16), rgb(9 4 11 / .22) 60%, rgb(9 4 11 / .56));
}

.vega-warden-hero::before {
  content: '';
  position: absolute;
  inset: -1.75rem 0 -2.5rem;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 46% 34%, rgb(248 113 113 / .16), transparent 63%),
    radial-gradient(ellipse at 50% 62%, rgb(13 6 13 / .44), transparent 72%);
  backdrop-filter: blur(7px) saturate(135%) brightness(.76);
  mask-image: radial-gradient(ellipse closest-side, #000 30%, rgb(0 0 0 / .75) 62%, transparent);
}

.vega-warden-pupil-scan {
  transform-box: view-box;
  transform-origin: 18px 12px;
  transform: scale(1.05, 1.25);
  animation: vega-warden-scan 6s cubic-bezier(.4, 0, .22, 1) infinite;
}

/* The slit just overshoots the curved lids, so the clip holds both tips against the eye. */
@keyframes vega-warden-scan {
  0%, 45.5%, 100% { transform: translateX(0) scale(1.05, 1.25); }
  15%, 36% { transform: translateX(-8px) scale(.72, 1.06); }
  55%, 80% { transform: translateX(6.5px) scale(.72, 1.1); }
}

