arguments.command:
set -eu
work=$(cat /tmp/vega-warden-type-current)
prior=$(cat /tmp/vega-warden-core-current)
sed -n '1,29p' "$prior/check.mjs" > "$work/check.mjs"
cat >> "$work/check.mjs" <<'EOF'
const heading = 'document.querySelector(".vega-warden-heading")'
await wait(`${heading} && [...document.fonts].some(f => f.family === 'Orbitron' && f.status === 'loaded')`)
await sleep(450)
for (const [width,height] of [[1440,960],[768,840],[390,844],[320,680]]) {
  await viewport(width,height)
  await sleep(150)
  const layout=await js(`(() => {
    const h=${heading};
    const style=getComputedStyle(h);
    const range=document.createRange();
    range.selectNodeContents(h);
    const lines=[...range.getClientRects()].filter(r => r.width > 0);
    const hero=h.closest('.vega-warden-hero').getBoundingClientRect();
    const status=h.nextElementSibling;
    return { text:h.textContent.trim(), family:style.fontFamily, weight:style.fontWeight,
      lines:lines.length, withinHero:lines.every(r=>r.left>=hero.left && r.right<=hero.right),
      belowEye:h.getBoundingClientRect().top > ${eye}.getBoundingClientRect().bottom,
      statusNotDisplayFont:!getComputedStyle(status).fontFamily.includes('Orbitron'),
      noHorizontalScroll:${overlay}.clientWidth === ${overlay}.scrollWidth,
    };
  })()`)
  assert.equal(layout.text,'VEGA HAS ASSUMED CONTROL')
  assert.match(layout.family,/^Orbitron,/)
  assert.equal(layout.weight,'900')
  assert.ok(layout.withinHero && layout.belowEye && layout.statusNotDisplayFont && layout.noHorizontalScroll, JSON.stringify(layout))
  assert.ok(width > 390 ? layout.lines === 2 : layout.lines <= 3, JSON.stringify(layout))
  console.log(`${width}px: ${layout.lines} line(s), Orbitron 900, no clipping`)
  if (width===1440||width===320) {
    const preview=await cdp('Page.captureScreenshot',{format:'png'})
    await writeFile(`/tmp/vega-warden-headline-${width}.png`,Buffer.from(preview.data,'base64'))
  }
}
ws.close()
EOF
profile=$(mktemp -d "$work/profile.XXXXXX")
node "$work/fixture.mjs" "$work/dist" > "$profile/fixture.port" & fixture=$!
google-chrome --headless --disable-gpu --no-sandbox --no-first-run --no-proxy-server --remote-debugging-port=0 --user-data-dir="$profile/chrome-profile" about:blank > "$profile/chrome.log" 2>&1 & chrome=$!
trap 'kill "$fixture" "$chrome" 2>/dev/null || true' EXIT
for i in $(seq 1 70); do
  if [ -s "$profile/fixture.port" ] && [ -s "$profile/chrome-profile/DevToolsActivePort" ]; then break; fi
  sleep .1
done
